def rotate90(arr):
    N = len(arr[0])
    rotate_matrix = [[0 for x in range(N)] for y in range(N)]

    for x in range(N):
        for y in range(N):
            rotate_matrix[y][N-1-x] = arr[x][y]
    return rotate_matrix

