    def push(self, item):
        # Push an item onto the top of the stack
        self.stack.append(item)

    def pop(self):
        # Pop an item off the top of the stack
        return self.stack.pop()

    def peek(self):
        # Get the top item off the stack
        return self.stack[-1]

