def is_prime(num):
    #Make sure the number is greater than or equal to 2 
    if num < 2:
        return False 
    # Check whether the number is divisible by any other number 
    for i in range(2, num):
        if num % i == 0:
            return False
    # If it is not divisible by any number, it is a prime number
    return True

def solveSudoku(board):
    find = find_empty(board)
    if not find:
        return True
    else:
        row, col = find

    for i in range(1,10):
        if valid(board, i, (row, col)):
            board[row][col] = i

            if solveSudoku(board):
                return True

            board[row][col] = 0

    return False

def valid(board, num, pos):
    # Check row
    for i in range(len(board[0])):
        if board[pos[0]][i] == num and pos[1] != i:
            return False

    # Check column
    for i in range(len(board)):
        if board[i][pos[1]] == num and pos[0] != i:
            return False

    # Check box
    box_x = pos[1] // 3
    box_y = pos[0] // 3

    for i in range(box_y*3, box_y*3 + 3):
        for j in range(box_x * 3, box_x*3 + 3):
            if board[i][j] == num and (i,j) != pos:
                return False

    return True 

def find_empty(board):
    for i in range(len(board)):
        for j in range(len(board[0])):
            if board[i][j] == 0:
                return (i, j)  # row, col

def align_columns(text):
        words = text.split(" ")
        max_len = 0
        for w in words:
            if len(w) > max_len:
                max_len = len(w)
        for i, w in enumerate(words):
            words[i] = w.ljust(max_len) 
        return " ".join(words)

