class Vector:
    def __init__(self, v):
        self.v = v

    def __str__(self):
        return str(self.v)

    def add(self, other):
        if len(self.v) != len(other.v):
            raise ValueError('Vectors must be of the same length.')

        return Vector([self.v[i] + other.v[i] for i in range(len(self.v))])

    def dot(self, other):
        if len(self.v) != len(other.v):
            raise ValueError('Vectors must be of the same length.')

        return sum(self.v[i] * other.v[i] for i in range(len(self.v)))

