def diamond(n):
    if n % 2 == 0:
        n += 1
    for i in range(n):
        if i < (n + 1)//2:
            for j in range((n - 3* i)//2):
                print(' ', end = '')
            for j in range(3*i + 1):
                print('*', end = '')
            for j in range((n - 3* i)//2):
                print(' ', end = '')
        else:
            for j in range(3* i - 3*(n // 2)):
                print(' ', end = '')
            for j in range(2*(n - i) - 1):
                print('*', end = '')
            for j in range(3* i - 3*(n // 2)):
                print(' ', end = '')
        print('')

